-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create policy "deal participants read archived listing images" on public.listing_images
  as permissive
  for select
  to anon, authenticated
  using ((listing_id IN ( SELECT public.my_deal_listing_ids() AS my_deal_listing_ids)) AND (EXISTS ( SELECT 1
   FROM public.listings l
  WHERE l.id = listing_images.listing_id AND l.status = 'archived'::text)));
